/**
 * Datasets — browser-local store (ADR-044 §8.2 + ADR-045, #220).
 *
 * Stores datasets that live ONLY in the browser: generated by the browser
 * executor (online HTTP TTS run client-side, no studio-backend) or imported
 * from a `wake-studio-dataset.zip` upload. Per ADR-045:
 *
 *   - **IndexedDB holds METADATA ONLY** (manifest + the storage ref + size) —
 *     never file bytes. The IndexedDB quota is small and a dataset zip can be
 *     hundreds of MB.
 *   - **The file bytes live in OPFS** (Origin Private File System) under
 *     `datasets/<id>/wake-studio-dataset.zip`, kept AS IMPORTED with no eager
 *     unpack. See `browser/opfs-dataset.ts`.
 *
 * List operations stay light (metadata only); bytes are read on demand from
 * OPFS: whole-archive only for explicit download/upload, single-clip for the
 * §8.3 listener.
 */

import type { DatasetManifest } from '@wake-studio/module-dataset'
import {
  DatasetStorageError,
  deleteDatasetZip,
  isOpfsAvailable,
  readDatasetZipBytes,
  writeDatasetZip,
} from './browser/opfs-dataset'

const DB_NAME = 'wake-studio-console'
const DB_VERSION = 1
const DATASET_STORE = 'local-datasets'

/** Where the bytes of a browser-local dataset live (IndexedDB never holds them). */
export interface LocalStorageRef {
  kind: 'opfs'
  /** Canonical zip file under `datasets/<id>/` (kept as imported — zip form). */
  format: 'zip'
}

/** The persisted record: METADATA ONLY (ADR-045) — no file bytes. */
export interface LocalDatasetRecord {
  id: string
  manifest: DatasetManifest
  sizeBytes: number
  savedAtMs: number
  storage: LocalStorageRef
}

/** The list view of a record (metadata only) — what the console rail reads. */
export interface LocalDatasetSummary {
  id: string
  manifest: DatasetManifest
  sizeBytes: number
  savedAtMs: number
}

/** Pre-#220 records kept the canonical zip bytes in IndexedDB (migrated on
 *  first list — the bytes move to OPFS and are stripped from the record). */
interface LegacyLocalDatasetRecord {
  id: string
  manifest: DatasetManifest
  zipBytes?: Uint8Array
  sizeBytes?: number
  savedAtMs?: number
}

let dbPromise: Promise<IDBDatabase> | null = null

function openDb(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise
  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION)
    req.onupgradeneeded = () => {
      const db = req.result
      if (!db.objectStoreNames.contains(DATASET_STORE)) {
        db.createObjectStore(DATASET_STORE, { keyPath: 'id' })
      }
    }
    req.onsuccess = () => resolve(req.result)
    req.onerror = () => reject(req.error)
  })
  return dbPromise
}

function tx<T>(
  mode: IDBTransactionMode,
  fn: (store: IDBObjectStore) => IDBRequest<T>,
): Promise<T> {
  return openDb().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const t = db.transaction(DATASET_STORE, mode)
        const req = fn(t.objectStore(DATASET_STORE))
        req.onsuccess = () => resolve(req.result)
        req.onerror = () => reject(req.error)
      }),
  )
}

function toSummary(record: LocalDatasetRecord): LocalDatasetSummary {
  return {
    id: record.id,
    manifest: record.manifest,
    sizeBytes: record.sizeBytes,
    savedAtMs: record.savedAtMs,
  }
}

/** One-time migration for pre-#220 records (zip bytes in IndexedDB → OPFS). */
async function migrateLegacyRecord(record: LegacyLocalDatasetRecord): Promise<LocalDatasetRecord> {
  const next: LocalDatasetRecord = {
    id: record.id,
    manifest: record.manifest,
    sizeBytes: record.sizeBytes ?? record.zipBytes?.byteLength ?? 0,
    savedAtMs: record.savedAtMs ?? Date.now(),
    storage: { kind: 'opfs', format: 'zip' },
  }
  if (record.zipBytes) {
    await writeDatasetZip(record.id, record.zipBytes)
  }
  await tx('readwrite', (store) => store.put(next))
  return next
}

/** List all browser-local datasets, most recently saved first. */
export async function listLocalDatasets(): Promise<LocalDatasetSummary[]> {
  const all = (await tx('readonly', (store) => store.getAll())) as Array<
    LocalDatasetRecord | LegacyLocalDatasetRecord
  >
  const summaries: LocalDatasetSummary[] = []
  for (const raw of all) {
    const legacy = raw as LegacyLocalDatasetRecord
    const record =
      'storage' in raw && raw.storage?.kind === 'opfs'
        ? (raw as LocalDatasetRecord)
        : await migrateLegacyRecord(legacy)
    summaries.push(toSummary(record))
  }
  return summaries.sort((a, b) => b.savedAtMs - a.savedAtMs)
}

/** Get one record (metadata only) by id. */
export async function getLocalDataset(id: string): Promise<LocalDatasetRecord | undefined> {
  return tx('readonly', (store) => store.get(id))
}

/** The full canonical zip bytes of one local dataset from OPFS (explicit
 *  download/upload only — the §8.3 listener reads single clips instead). */
export async function getLocalDatasetZip(id: string): Promise<Uint8Array | null> {
  if (!isOpfsAvailable()) return null
  return readDatasetZipBytes(id)
}

/** Persist a browser-generated/imported dataset: zip bytes → OPFS, metadata →
 *  IndexedDB. Returns the stored summary. */
export async function saveLocalDataset(
  manifest: DatasetManifest,
  zipBytes: Uint8Array,
): Promise<LocalDatasetSummary> {
  if (!isOpfsAvailable()) {
    throw new DatasetStorageError(
      'This browser has no Origin Private File System (OPFS) — the dataset cannot be stored locally.',
    )
  }
  await writeDatasetZip(manifest.id, zipBytes)
  const record: LocalDatasetRecord = {
    id: manifest.id,
    manifest,
    sizeBytes: zipBytes.byteLength,
    savedAtMs: Date.now(),
    storage: { kind: 'opfs', format: 'zip' },
  }
  await tx('readwrite', (store) => store.put(record))
  return toSummary(record)
}

/** Update ONLY the manifest of a stored dataset (e.g. a new cloud ref after an
 *  upload) — the OPFS bytes are untouched. Throws when the dataset is absent. */
export async function patchLocalDatasetManifest(
  id: string,
  manifest: DatasetManifest,
): Promise<void> {
  const existing = await getLocalDataset(id)
  if (!existing) throw new DatasetStorageError(`Local dataset “${id}” is not in the store.`)
  await tx('readwrite', (store) =>
    store.put({ ...existing, manifest, savedAtMs: Date.now() }),
  )
}

/** Delete one local dataset (OPFS bytes + IndexedDB metadata). */
export async function deleteLocalDataset(id: string): Promise<void> {
  await deleteDatasetZip(id)
  await tx('readwrite', (store) => store.delete(id))
}